<?php
namespace Azula\SmsStudio;

/** Uses the existing six-page shell, composer, audience table, history and analytics. */
final class CampaignFlowScreen
{
    public static function enhance(string $html):string
    {
        $management='';$html=preg_replace_callback('/<section class="azs-scheduling m6-management">.*?<\/section>/s',function($m)use(&$management){$management=$m[0];return '';},$html,1);$management=str_replace('<th>Scheduled / Egypt</th>','',$management);$html=preg_replace('/<div data-view="campaigns">/','<div data-view="campaigns"><section class="flow-list-intro"><h2>Campaigns</h2><p>Create a campaign, or open an existing one. Submitted history stays protected.</p></section>'.$management.'</div><div data-view="builder" hidden>',$html,1);
        $name='';$html=preg_replace_callback('/<div class="m6-campaign-name">.*?<\/div>/s',function($m)use(&$name){$name=$m[0];return '';},$html,1);$name='<div class="flow-name"><label class="azs-label" for="m6-name">Campaign Name <span aria-hidden="true">*</span></label><input id="m6-name" maxlength="190" required aria-required="true" autocomplete="off" placeholder="e.g. Azula October collection"><p id="flow-name-error" role="status"></p></div>';
        $html=str_replace('<section data-panel="0" class="azs-panel">','<section data-panel="0" class="azs-panel">'.$name,$html);
        $html=str_replace('Select audience</span>','Campaign Setup</span>',$html);$html=str_replace('Review audience</span>','Audience Review</span>',$html);$html=str_replace('Schedule & save</span>','Send or Schedule</span>',$html);
        $html=str_replace('<section data-panel="2"','<section data-panel="1" class="azs-panel" hidden><div id="flow-audience-anchor"></div></section><section data-panel="2"',$html);
        $html=preg_replace('~<div hidden><section class="azs-scheduling"><span class="azs-eyebrow">CONTROLLED TEST / MANUAL ONLY</span>.*?</section></div>~s','<div hidden><span id="controlled-status"></span><span id="controlled-package"></span><select id="controlled-language"><option value="1"></option></select><button id="controlled-prepare"></button><button id="controlled-approve"></button><button id="activity-refresh"></button><input id="controlled-confirm-text"><input id="controlled-ack" type="checkbox"><button id="controlled-confirm"></button><span id="controlled-result"></span></div>',$html,1);
        $html=preg_replace('/<section class="m6-approval">.*?<\/section>/s','',$html,1);
        $html=preg_replace('/<section data-panel="4".*?<\/section>/s',self::timing(),$html,1);
        $html=str_replace('<div data-view="audience" hidden>','<div data-view="audience" id="flow-audience-home" hidden>',$html);
        $html=str_replace('<button class="azs-btn primary" data-next="4">Schedule & save →</button>','<button class="azs-btn primary" data-next="4">Send or Schedule →</button>',$html);
        $html=str_replace('<b>AZULA</b>','<b id="flow-preview-sender">Sender name unverified</b>',$html);
        $html=str_replace('<label class="azs-label" for="sms-message">','<p id="flow-sender-note" class="azs-coverage">Sender configuration is being checked.</p><label class="azs-label" for="sms-message">',$html);
        $html=str_replace('<div class="azs-actions"><button id="save-message"','<label for="flow-language">Provider language</label><select id="flow-language"><option value="1">English</option><option value="2">Arabic</option><option value="3">Unicode</option></select><div class="azs-actions"><button id="save-message"',$html);
        $html=str_replace('<div class="azs-builder-head">','<button class="azs-text-btn" id="flow-back-list">← Campaigns</button><div class="azs-builder-head">',$html);
        $html=str_replace('<span class="azs-badge">Bulk & automatic Live blocked</span>','<span class="azs-badge">Bulk & automatic Live blocked</span>',$html);
        $gate=<<<'HTML'
<section id="flow-live-settings" class="azs-scheduling" hidden><h3>Manual one-recipient Live sending</h3><label for="flow-live-enabled"><input id="flow-live-enabled" type="checkbox" role="switch"> Enable manual one-recipient Live SMS sending</label><p>Allow the site owner to manually submit an SMS Misr Live (1) campaign containing exactly one validated recipient after reviewing and confirming the campaign. Bulk Live and automatic Live sending remain disabled.</p><p id="flow-live-state" role="status">Checking backend authorization…</p><button id="flow-live-save" class="azs-btn secondary" disabled>Save manual Live setting</button><p id="flow-live-result" role="status"></p></section>
HTML;
        if(function_exists('current_user_can')&&current_user_can('manage_options')&&current_user_can('manage_azula_sms_settings')&&current_user_can('approve_azula_sms_campaigns')&&current_user_can('dispatch_azula_sms_campaigns'))$html=str_replace('<p id="m6-health">',$gate.'<p id="m6-health">',$html);
        if(M7Settings::modern()&&current_user_can('manage_options')&&current_user_can('manage_azula_sms_settings'))$html=str_replace('<p id="m6-health">','<section class="azs-scheduling" id="m7-settings"><h3>Branded links & tracking collection</h3><label><input type="checkbox" role="switch" id="m7-enabled" disabled> Tracking collection</label><p>OFF collects no link events or browser journey context. ON records minimal anonymous observations, subject to consent. Enabling collection never enables sending.</p><label for="m7-path">Short-link path</label><input id="m7-path" value="s" maxlength="24" autocomplete="off"><p>Configure before creating links. Issued paths remain locked to preserve URLs.</p><button class="azs-btn secondary" id="m7-save" disabled>Save tracking settings</button><p id="m7-status" role="status"></p><button class="azs-btn secondary" id="m7-diagnostic">Run tracking diagnostic</button><pre id="m7-diagnostic-result" style="white-space:pre-wrap" role="status"></pre><a id="m7-probe" hidden target="_blank" rel="noreferrer noopener">Open five-minute route test (no SMS)</a></section><p id="m6-health">',$html);
        if(M8Tokens::modern())$html=str_replace('<h3>Campaign performance</h3>','<section class="azs-scheduling"><h3>Activity & recorded event values</h3><p>Cart values exclude taxes, shipping and cart-level coupons; checkout values include payable discounts, shipping, taxes and fees as observed. Only attributed purchase revenue is sales.</p><details><summary>Metric and attribution definitions</summary><p id="m8-definitions">Event sums are not revenue. Unique tracked recipients means distinct SMS-owned campaign-recipient records, not verified people or WooCommerce customer accounts.</p></details><div class="azs-table-wrap"><table><thead><tr><th>Activity</th><th>Total events</th><th>Unique tracked recipients</th><th>Recorded value / EGP</th><th>Value coverage / missing values</th></tr></thead><tbody id="m8-events"></tbody></table></div><p id="m8-abandonment" role="status"></p><button class="azs-btn secondary" id="m8-cost-reconcile">Reconcile saved provider cost evidence</button><p id="m8-cost-status" role="status"></p></section><h3>Campaign performance</h3>',$html);
        $settings=<<<'HTML'
<section class="flow-sender-settings"><h3>Approved sender name</h3><p>The provider Sender ID may be a secret token. Confirm the handset-facing name in your SMS Misr account, then save that mapping here. The actual provider request continues to use the configured Sender ID value.</p><label for="flow-sender-label">Approved alphanumeric name</label><input id="flow-sender-label" maxlength="11" autocomplete="off" placeholder="AzulaSports"><button id="flow-sender-save" class="azs-btn secondary">Save provider-verified sender name</button><p id="flow-sender-status" role="status"></p></section>
HTML;
        $html=str_replace('<p id="provider-secret-status"',$settings.'<p id="provider-secret-status"',$html);
        $html=str_replace('id="provider-sender" type="text"','id="provider-sender" type="password"',$html);
        // Keep legacy controller targets inert, without user-facing technical approvals or phrases.
        $hidden='<div hidden aria-hidden="true"><input id="schedule-local" type="datetime-local"><select id="schedule-offset"></select><span id="schedule-time-help"></span><span id="schedule-eligibility"></span><span id="timing-review"></span><span id="final-count"></span><button id="schedule-save"></button><button id="save-review"></button><span id="review-result"></span></div>';
        $dialog=<<<'HTML'
<dialog id="flow-confirm-dialog" aria-labelledby="flow-confirm-title"><div class="flow-dialog-head"><span class="azs-eyebrow">FINAL CONFIRMATION</span><h2 id="flow-confirm-title">Confirm SMS campaign</h2></div><dl id="flow-confirm-facts"></dl><p class="azs-label">Message</p><div id="flow-confirm-message" class="azs-review-card" dir="auto"></div><p id="flow-confirm-warning" class="azs-coverage"></p><div class="azs-actions"><button id="flow-confirm-cancel" class="azs-btn secondary">Cancel</button><button id="flow-confirm-submit" class="azs-btn primary">Confirm & Send</button></div><p id="flow-confirm-error" role="alert"></p></dialog>
HTML;
        $html=str_replace('M5 + M6 / v0.6.0 REVIEW','v0.8.0 / STAGING REVIEW',$html);
        return preg_replace('~</section></main></div>\s*$~',$hidden.$dialog.'</section></main></div>',$html);
    }
    private static function timing():string{return <<<'HTML'
<section data-panel="4" class="azs-panel" hidden><span class="azs-kicker">05 / SEND OR SCHEDULE</span><h2>Choose your campaign’s moment.</h2><div class="azs-timing-options"><label class="azs-timing-option"><input type="radio" name="flow-timing" value="now" checked> Send Now</label><label class="azs-timing-option"><input type="radio" name="flow-timing" value="later"> Schedule for Later</label></div><div id="flow-schedule-fields" class="flow-form-grid" hidden><label>Date in Egypt<input id="flow-date" type="date"></label><label>Time in Egypt<input id="flow-time" type="time" step="60"></label><label>Verified occurrence<select id="flow-offset"><option value="">Choose a date and time</option></select></label><p id="flow-time-status" role="status">Africa/Cairo · daylight-saving aware · stored in UTC.</p></div><p id="flow-action-status" class="azs-coverage" role="status">Review the campaign in Step 4 before sending.</p><button id="flow-primary" class="azs-btn primary" disabled>Send SMS Now</button><p id="flow-result" role="status" aria-live="polite"></p></section>
HTML;}
}
